DROP TABLE IF EXISTS database_profiles_negara;
CREATE TABLE IF NOT EXISTS database_profiles_negara (
    id INT PRIMARY KEY,
    country_slug VARCHAR(100) NOT NULL,
    name_id VARCHAR(100) NOT NULL,
    name_en VARCHAR(100) NOT NULL,
    capital VARCHAR(100) NOT NULL,
    lon DECIMAL(9, 6) NOT NULL,
    lat DECIMAL(9, 6) NOT NULL,
    flag VARCHAR(10) NOT NULL,
    jumlah_penduduk BIGINT NOT NULL,
    anggaran BIGINT NOT NULL,
    pendapatan_nasional BIGINT NOT NULL,
    religion VARCHAR(100) NOT NULL,
    ideology VARCHAR(100) NOT NULL,
    un_vote INT NOT NULL,
    reputasi_diplomatik VARCHAR(100) NOT NULL,
    pengaruh_global INT NOT NULL,
    peringkat_diplomasi INT NOT NULL,
    sikap VARCHAR(100) NOT NULL,
    kekuatan_lunak INT NOT NULL,
    kekuatan_keras INT NOT NULL,
    prestise_diplomatik INT NOT NULL
);

